SELECT '1. change_order_dates（6 參數）存在且尚未含檢查段' AS 項目, (SELECT position('ORDER_MODULE_GUARD_V1' IN p.prosrc) = 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)')) AS 結果
UNION ALL SELECT '2. 錨點（換行 BEGIN 換行）在 change_order_dates 只出現 1 次', (SELECT (length(p.prosrc) - length(replace(p.prosrc, E'\nBEGIN\n', ''))) / length(E'\nBEGIN\n') = 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.change_order_dates(uuid, date, date, text, text, text)'))
UNION ALL SELECT '3. staff_can_edit_module(uuid, text) 存在', to_regprocedure('public.staff_can_edit_module(uuid, text)') IS NOT NULL
UNION ALL SELECT '4. 20261030090000 已上線：update_order_with_context 只剩 service_role', NOT has_function_privilege('anon', to_regprocedure('public.update_order_with_context(uuid, jsonb, text, text, text, text, jsonb, jsonb)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.update_order_with_context(uuid, jsonb, text, text, text, text, jsonb, jsonb)'), 'EXECUTE')
UNION ALL SELECT '5. sync_order_rooms_v1、clear_order_room_pricing_template 簽章存在', to_regprocedure('public.sync_order_rooms_v1(uuid, timestamp with time zone, jsonb)') IS NOT NULL AND to_regprocedure('public.clear_order_room_pricing_template(uuid)') IS NOT NULL
UNION ALL SELECT '6. 相關函式沒有同名多載（共 10 支）', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('change_order_dates', 'admin_delete_order', 'attach_trip_products_to_recent_order', 'clear_order_room_pricing_template', 'sync_order_rooms_v1', 'update_order_fields_v1', 'update_paid_order_addons_v3', 'update_paid_order_discount_v2', 'staff_can_edit_module', 'get_staff_module_permission')) = 10;

SELECT p.oid::regprocedure::text AS 函式, p.prosecdef AS security_definer, COALESCE(p.proacl::text, '(NULL＝預設 PUBLIC 可執行)') AS 目前授權,
       has_function_privilege('anon', p.oid, 'EXECUTE') AS anon可執行, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS authenticated可執行, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_role可執行,
       md5(replace(p.prosrc, E'\r', '')) AS 指紋, md5(replace(p.prosrc, E'\r', '')) = CASE p.proname WHEN 'change_order_dates' THEN 'c929d74bdf8f6fa763c1e29f76eeb70f' WHEN 'admin_delete_order' THEN 'c475f3c838693c49de1c884c68f59e2e' WHEN 'attach_trip_products_to_recent_order' THEN '22f24eea56e8a00a55bcb0f034691222' WHEN 'clear_order_room_pricing_template' THEN '3e2a820ae3b78d49f689f270bbc68cd2' WHEN 'sync_order_rooms_v1' THEN '957646923f7e28e9fe7c75b50ed26643' WHEN 'update_order_fields_v1' THEN '281dd4b043ecf7204d331c1419be446b' WHEN 'update_paid_order_addons_v3' THEN '6f33325215f67094a7e5992c02ef9943' WHEN 'update_paid_order_discount_v2' THEN '072ae35e8cbadaf141d3ee5cc5ff0d3f' WHEN 'staff_can_edit_module' THEN '2bc9cdfb8f98b1ea26c361f9dca1c095' WHEN 'get_staff_module_permission' THEN 'aea42e17d7f8d452d1d241286e70dcb8' END AS 與本機基準相同
FROM pg_proc p
WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('change_order_dates', 'admin_delete_order', 'attach_trip_products_to_recent_order', 'clear_order_room_pricing_template', 'sync_order_rooms_v1', 'update_order_fields_v1', 'update_paid_order_addons_v3', 'update_paid_order_discount_v2', 'staff_can_edit_module', 'get_staff_module_permission')
ORDER BY 1;
